#include <string>

struct Sensor {
    int id;
};

// Passagem por referência constante: zero cópia e seguro
void lerSensor(const Sensor& s) {
    // std::unique_ptr libera a memória automaticamente no fim do bloco
    auto ptr = std::make_unique<Sensor>(Sensor{s.id});
}

